"""Applies the SQL files in migrations/ to a SQLite database, oldest first."""
import re
import sqlite3
import sys
from pathlib import Path

DIR = Path(__file__).parent / "migrations"
APPLIED = []


def _num(path):
    return int(re.match(r"(\d+)", path.name).group(1))


def files():
    return sorted((p for p in DIR.iterdir() if p.suffix == ".sql"), key=_num)


def apply(conn):
    for path in files():
        conn.executescript(path.read_text())
        APPLIED.append(path.name)


def connect(url=":memory:"):
    conn = sqlite3.connect(url)
    apply(conn)
    return conn


if __name__ == "__main__":
    connect(sys.argv[1] if len(sys.argv) > 1 else ":memory:")
    print("applied", len(APPLIED), "migrations")

